from pathlib import Path
from PIL import Image, ImageChops
import os
before=Path(os.environ['SNAP_BEFORE'])
after=Path('e2e/visual/admin.spec.ts-snapshots')
files=sorted(after.glob('admin-list-consistency-*-chromium-darwin.png'))
if len(files) != 6:
    raise SystemExit(f'expected 6 screenshots, found {len(files)}')
for path in files:
    baseline=before / path.name
    with Image.open(baseline) as a, Image.open(path) as b:
        if a.size != b.size or ImageChops.difference(a.convert('RGBA'), b.convert('RGBA')).getbbox() is not None:
            raise SystemExit(f'visual regression after CSS split: {path.name}')
print('admin_css_visual_compare=6/6 pixel-identical')
